CREATE DATABASE IF NOT EXISTS heibox DEFAULT CHARACTER SET utf8mb4; USE heibox;
CREATE TABLE users(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(40) NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,avatar MEDIUMTEXT NULL,bio VARCHAR(200) NULL,role VARCHAR(20) NOT NULL DEFAULT 'user',status VARCHAR(20) NOT NULL DEFAULT 'active',muted_until TIMESTAMP NULL DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE communities(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,description TEXT,owner_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE posts(id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(160) NOT NULL,content TEXT,media JSON,community_id INT NOT NULL,user_id INT NOT NULL,pinned TINYINT(1) NOT NULL DEFAULT 0,featured TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(community_id) REFERENCES communities(id),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_posts_created(created_at),INDEX idx_posts_community(community_id,created_at));
CREATE TABLE comments(id INT PRIMARY KEY AUTO_INCREMENT,post_id INT NOT NULL,user_id INT NOT NULL,content VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_comments_post(post_id,created_at));
CREATE TABLE likes(post_id INT NOT NULL,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(post_id,user_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE reports(id INT PRIMARY KEY AUTO_INCREMENT,post_id INT NOT NULL,user_id INT NOT NULL,reason VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,handled_at TIMESTAMP NULL,handled_by INT NULL,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_reports_status(status,created_at));
CREATE TABLE notifications(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,actor_id INT NULL,actor_name VARCHAR(40) NULL,type VARCHAR(20) NOT NULL,post_id INT NULL,comment_id INT NULL,body VARCHAR(200) NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,INDEX idx_notifications_user(user_id,is_read,created_at));
